const upsertCurrentAssetDigest = `-- name: UpsertCurrentAssetDigest :one
INSERT INTO asset_digests (
    asset_id,
    kind,
    value,
    is_current,
    reason,
    recorded_at
)
VALUES ($1, $2, $3, TRUE, $4, $5)
ON CONFLICT (asset_id, kind, value) DO UPDATE
SET is_current = TRUE,
    reason = EXCLUDED.reason,
    recorded_at = EXCLUDED.recorded_at
RETURNING asset_id, kind, value, is_current, reason, recorded_at
`

type UpsertCurrentAssetDigestParams struct {
	AssetID    string
	Kind       string
	Value      string
	Reason     string
	RecordedAt time.Time
}

func (q *Queries) UpsertCurrentAssetDigest(ctx context.Context, arg UpsertCurrentAssetDigestParams) (AssetDigest, error) {
	row := q.db.QueryRow(ctx, upsertCurrentAssetDigest,
		arg.AssetID,
		arg.Kind,
		arg.Value,
		arg.Reason,
		arg.RecordedAt,
	)
	var i AssetDigest
	err := row.Scan(
		&i.AssetID,
		&i.Kind,
		&i.Value,
		&i.IsCurrent,
		&i.Reason,
		&i.RecordedAt,
	)
	return i, err
}
